const input = $input.first().json;
const cartId = typeof input.cart_id === 'number' ? input.cart_id : null;

const copilotApiBase = $env.COPILOT_API_BASE || '';
const marker = '/wp-json';
const idx = copilotApiBase.indexOf(marker);
const siteRoot = idx === -1 ? copilotApiBase : copilotApiBase.slice(0, idx);

const wpUser = $env.WP_APP_USER || '';
const wpPassword = $env.WP_APP_PASSWORD || '';
const wpAuthHeader = 'Basic ' + Buffer.from(`${wpUser}:${wpPassword}`).toString('base64');

return [{
  json: {
    cartId,
    siteRoot,
    wpAuthHeader,
    anthropicApiKey: $env.ANTHROPIC_API_KEY || '',
  }
}];

const prep = $('prepare-request').first().json;
const response = $input.first().json;
const carts = response.carts || [];

const candidates = carts.filter(c => !c.recovered);

let target = null;
if (prep.cartId !== null) {
  target = candidates.find(c => c.id === prep.cartId) || null;
} else if (candidates.length > 0) {
  const sorted = [...candidates].sort((a, b) => {
    if (b.cart_total !== a.cart_total) return b.cart_total - a.cart_total;
    return a.minutes_since_update - b.minutes_since_update;
  });
  target = sorted[0];
}

if (!target) {
  return [{ json: { found: false } }];
}

const currency = target.currency;
const lines = [
  `Customer: ${target.first_name}`,
  `Cart abandoned: ${target.minutes_since_update} minutes ago`,
  `Currency: ${currency}`,
  'Items:',
];
for (const item of target.items) {
  lines.push(`- ${item.name} x${item.quantity} @ ${currency} ${item.price.toFixed(2)} = ${currency} ${item.line_total.toFixed(2)}`);
}
lines.push(`Cart total: ${currency} ${target.cart_total.toFixed(2)}`);

return [{
  json: {
    found: true,
    cart: {
      id: target.id,
      email: target.email,
      first_name: target.first_name,
      cart_total: target.cart_total,
      currency: target.currency,
    },
    promptText: lines.join('\n'),
  }
}];

const prep = $('prepare-request').first().json;
const selected = $input.first().json;

const systemPrompt = `You are a customer-retention email copywriter for an online store selling electronics and lifestyle products. Write a short, warm, low-pressure cart-recovery email for the customer described in the user message.

Rules:
- Use ONLY the facts given: product names, quantities, prices, cart total, currency, first name.
- Do NOT invent stock levels, deadlines, discounts, coupon codes, or any claim not present in the provided data.
- Do not offer or mention any discount, percentage off, or promo code - none has been issued for this email.
- Keep the tone friendly and low-pressure, in English.
- Respond with ONLY a single JSON object, no markdown code fences, no extra commentary, in exactly this shape:
{"subject": "<email subject line>", "body": "<plain text email body>"}`;

return [{
  json: {
    anthropicApiKey: prep.anthropicApiKey,
    requestBody: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 500,
      system: systemPrompt,
      messages: [{ role: 'user', content: selected.promptText }],
    },
  }
}];

const payload = $input.first().json;
const textBlocks = (payload.content || [])
  .filter(b => b.type === 'text')
  .map(b => b.text || '');
let text = textBlocks.join('').trim();

if (text.startsWith('```')) {
  const firstNewline = text.indexOf('\n');
  text = firstNewline === -1 ? text.slice(3) : text.slice(firstNewline + 1);
  if (text.endsWith('```')) text = text.slice(0, -3);
  text = text.trim();
}

if (!text) {
  return [{ json: { parsed: false, error: `empty text; stop_reason=${payload.stop_reason}` } }];
}

try {
  const draft = JSON.parse(text);
  if (!draft.subject || !draft.body) {
    return [{ json: { parsed: false, error: 'missing subject/body in LLM response' } }];
  }
  return [{ json: { parsed: true, subject: draft.subject, body: draft.body } }];
} catch (e) {
  return [{ json: { parsed: false, error: `JSON parse failed: ${e.message}` } }];
}

const parsed = $input.first().json;
const cart = $('select-target-cart').first().json.cart;

return [{
  json: {
    status: 'ok',
    cart,
    subject: parsed.subject,
    body: parsed.body,
  }
}];
